using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Options with the default reflection-based resolver
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// 1️⃣ GetTypeInfo<T>() — returns strongly-typed JsonTypeInfo<T>
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person> → Type={personInfo.Type.Name}, Kind={personInfo.Kind}");

// Use it to serialize
string json = JsonSerializer.Serialize(new Person("Ada", 38), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2️⃣ TryGetTypeInfo<T>() — probe without throwing
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded → {info!.Type.Name}");
}

// Now demonstrate a case where metadata is NOT available:
// Use a source-gen context that only knows about Person.
var limited = new JsonSerializerOptions { TypeInfoResolver = LimitedContext.Default };

if (limited.TryGetTypeInfo<int>(out JsonTypeInfo<int>? intInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int> succeeded → {intInfo!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int> returned false — metadata not available (no exception!)");
}

// Types & source-gen context
public record Person(string Name, int Age);

[JsonSerializable(typeof(Person))]
public partial class LimitedContext : JsonSerializerContext { }

